package main

import (
	"fmt"
	"html/template"
	"net/http"
	"net/http/httptest"

	"github.com/gin-gonic/gin"
)

func main() {
	gin.SetMode(gin.ReleaseMode)
	r := gin.New()
	r.SetHTMLTemplate(template.Must(template.New("hi").Parse("<h1>hello {{.}}</h1>")))

	r.GET("/string", func(c *gin.Context) {
		c.String(http.StatusOK, "hello %s", "gin")
	})
	r.GET("/json", func(c *gin.Context) {
		c.JSON(http.StatusOK, gin.H{"msg": "ok"})
	})
	r.GET("/html", func(c *gin.Context) {
		c.HTML(http.StatusOK, "hi", "gin")
	})
	r.GET("/data", func(c *gin.Context) {
		c.Data(http.StatusOK, "application/octet-stream", []byte{0x01, 0x02})
	})
	r.GET("/redirect", func(c *gin.Context) {
		c.Redirect(http.StatusFound, "/json")
	})

	for _, path := range []string{"/string", "/json", "/html", "/data", "/redirect"} {
		w := httptest.NewRecorder()
		req := httptest.NewRequest(http.MethodGet, path, nil)
		r.ServeHTTP(w, req)
		fmt.Printf("%-9s status=%d type=%-30q location=%q body=%q\n",
			path, w.Code, w.Header().Get("Content-Type"), w.Header().Get("Location"), w.Body.String())
	}
}

package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"

	"github.com/gin-gonic/gin"
)

func main() {
	gin.SetMode(gin.ReleaseMode)
	r := gin.New()

	// 默认：render.JSON 写 application/json; charset=utf-8
	r.GET("/default", func(c *gin.Context) {
		c.JSON(http.StatusOK, gin.H{"hello": "gin"})
	})

	// 自己先设 Content-Type：Gin 发现已经有值就不再覆盖
	r.GET("/custom", func(c *gin.Context) {
		c.Header("Content-Type", "application/vnd.api+json")
		c.JSON(http.StatusOK, gin.H{"hello": "gin"})
	})

	// 手工拼 JSON 字符串：不会自动带 Content-Type
	r.GET("/raw", func(c *gin.Context) {
		c.Data(http.StatusOK, "application/json", []byte(`{"hello":"gin"}`))
	})

	for _, path := range []string{"/default", "/custom", "/raw"} {
		w := httptest.NewRecorder()
		req := httptest.NewRequest(http.MethodGet, path, nil)
		r.ServeHTTP(w, req)
		fmt.Printf("%-8s type=%q body=%s\n", path, w.Header().Get("Content-Type"), w.Body.String())
	}
}

package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"

	"github.com/gin-gonic/gin"
)

func main() {
	gin.SetMode(gin.ReleaseMode)
	r := gin.New()

	// 直接把状态码交给渲染函数
	r.GET("/teapot", func(c *gin.Context) {
		c.JSON(http.StatusTeapot, gin.H{"msg": "我是个茶壶"})
	})

	// 先设状态码再写 body，状态码依然生效
	r.GET("/created", func(c *gin.Context) {
		c.Status(http.StatusCreated)
		c.Writer.WriteString("已创建")
	})

	// body 已经写出之后再改状态码：Gin 会忽略
	r.GET("/late", func(c *gin.Context) {
		c.String(http.StatusOK, "body first")
		c.Status(http.StatusNotFound)
	})

	for _, path := range []string{"/teapot", "/created", "/late"} {
		w := httptest.NewRecorder()
		req := httptest.NewRequest(http.MethodGet, path, nil)
		r.ServeHTTP(w, req)
		fmt.Printf("%-8s status=%d body=%q\n", path, w.Code, w.Body.String())
	}
}

