import (
	"fmt"
	"net/http"
	"net/http/httptest"

	"github.com/gin-gonic/gin"
)

func main() {
	gin.SetMode(gin.ReleaseMode)
	r := gin.New()

	// 标准的 204：只有状态码，没有 body
	r.DELETE("/cache", func(c *gin.Context) {
		c.Status(http.StatusNoContent)
	})

	// c.JSON(204, ...) 的 body 会被 Gin 拦掉，但会留下 Content-Type
	r.GET("/json204", func(c *gin.Context) {
		c.JSON(http.StatusNoContent, gin.H{"ok": true})
	})

	cases := []struct {
		method string
		path   string
	}{
		{http.MethodDelete, "/cache"},
		{http.MethodGet, "/json204"},
	}
	for _, cs := range cases {
		w := httptest.NewRecorder()
		req := httptest.NewRequest(cs.method, cs.path, nil)
		r.ServeHTTP(w, req)
		fmt.Printf("%-9s status=%d type=%q body=%q\n",
			cs.path, w.Code, w.Header().Get("Content-Type"), w.Body.String())
	}
}

