import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"time"

	"github.com/gin-gonic/gin"
)

// 统一响应体：code 是业务码，0 表示成功
type Response struct {
	Code      int    `json:"code"`
	Message   string `json:"message"`
	Data      any    `json:"data,omitempty"`
	RequestID string `json:"request_id,omitempty"`
}

// 成功响应
func Success(c *gin.Context, data any) {
	c.JSON(http.StatusOK, Response{
		Code:      0,
		Message:   "ok",
		Data:      data,
		RequestID: c.GetString("request_id"),
	})
}

// 失败响应：Abort 保证后面的 handler 不再执行
func Fail(c *gin.Context, status int, code int, message string) {
	c.AbortWithStatusJSON(status, Response{
		Code:      code,
		Message:   message,
		RequestID: c.GetString("request_id"),
	})
}

// 请求 ID 中间件：统一塞进响应头和响应体
func RequestID() gin.HandlerFunc {
	return func(c *gin.Context) {
		id := fmt.Sprintf("req-%d", time.Now().UnixNano())
		c.Set("request_id", id)
		c.Header("X-Request-Id", id)
		c.Next()
	}
}

func main() {
	gin.SetMode(gin.ReleaseMode)
	r := gin.New()
	r.Use(RequestID())

	r.GET("/users/:id", func(c *gin.Context) {
		if c.Param("id") != "1" {
			Fail(c, http.StatusNotFound, 40400, "用户不存在")
			return
		}
		Success(c, gin.H{"id": 1, "name": "forty"})
	})

	for _, path := range []string{"/users/1", "/users/2"} {
		w := httptest.NewRecorder()
		req := httptest.NewRequest(http.MethodGet, path, nil)
		r.ServeHTTP(w, req)
		fmt.Printf("%-9s status=%d trace=%s body=%s\n",
			path, w.Code, w.Header().Get("X-Request-Id"), w.Body.String())
	}
}

