import (
	"errors"
	"fmt"
	"net/http"
	"net/http/httptest"

	"github.com/gin-gonic/gin"
)

// BizError 是业务错误：Code 给前端用，Err 只进日志
type BizError struct {
	Code int
	Msg  string
	Err  error
}

func (e *BizError) Error() string {
	return fmt.Sprintf("biz error %d: %v", e.Code, e.Err)
}

// 业务层返回 BizError
func loadUser(id string) (gin.H, error) {
	if id != "1" {
		return nil, &BizError{
			Code: 10001,
			Msg:  "用户不存在",
			Err:  errors.New("db: sql: no rows in result set"),
		}
	}
	return gin.H{"id": id, "name": "forty"}, nil
}

// 统一错误处理中间件：handler 只负责 c.Error(err)
func ErrorHandler() gin.HandlerFunc {
	return func(c *gin.Context) {
		c.Next()
		if len(c.Errors) == 0 || c.Writer.Written() {
			return
		}
		err := c.Errors.Last().Err
		var biz *BizError
		if errors.As(err, &biz) {
			// 内部错误只进日志，不返回给用户
			fmt.Printf("internal error: %v\n", biz.Err)
			c.AbortWithStatusJSON(http.StatusBadRequest, gin.H{
				"code":    biz.Code,
				"message": biz.Msg,
			})
			return
		}
		c.AbortWithStatusJSON(http.StatusInternalServerError, gin.H{
			"code":    50000,
			"message": "服务器内部错误",
		})
	}
}

func main() {
	gin.SetMode(gin.ReleaseMode)
	r := gin.New()
	r.Use(ErrorHandler())

	r.GET("/users/:id", func(c *gin.Context) {
		user, err := loadUser(c.Param("id"))
		if err != nil {
			_ = c.Error(err) // 挂到 c.Errors，交给错误中间件统一输出
			return
		}
		c.JSON(http.StatusOK, user)
	})

	for _, path := range []string{"/users/1", "/users/2"} {
		w := httptest.NewRecorder()
		req := httptest.NewRequest(http.MethodGet, path, nil)
		r.ServeHTTP(w, req)
		fmt.Printf("%-9s status=%d body=%s\n", path, w.Code, w.Body.String())
	}
}

