import (
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"runtime/debug"

	"github.com/gin-gonic/gin"
)

// 写法一：用 Gin 自带的 CustomRecovery，只替换「出错之后怎么回响应」
func customRecovery() gin.HandlerFunc {
	return gin.CustomRecoveryWithWriter(io.Discard, func(c *gin.Context, err any) {
		fmt.Printf("[panic] %v\n%s\n", err, debug.Stack())
		c.AbortWithStatusJSON(http.StatusInternalServerError, gin.H{
			"code":    50000,
			"message": "服务器内部错误",
		})
	})
}

// 写法二：自己写一个功能等价的中间件
func myRecovery() gin.HandlerFunc {
	return func(c *gin.Context) {
		defer func() {
			if rec := recover(); rec != nil {
				fmt.Printf("[panic] %v\n%s\n", rec, debug.Stack())
				c.AbortWithStatusJSON(http.StatusInternalServerError, gin.H{
					"code":    50000,
					"message": "服务器内部错误",
				})
			}
		}()
		c.Next()
	}
}

func main() {
	gin.SetMode(gin.ReleaseMode)
	r := gin.New()
	r.GET("/custom", customRecovery(), func(c *gin.Context) { panic("custom boom") })
	r.GET("/mine", myRecovery(), func(c *gin.Context) { panic("my boom") })

	for _, path := range []string{"/custom", "/mine"} {
		w := httptest.NewRecorder()
		req := httptest.NewRequest(http.MethodGet, path, nil)
		r.ServeHTTP(w, req)
		fmt.Printf("%-7s status=%d body=%s\n", path, w.Code, w.Body.String())
	}
}

