import (
	"fmt"
	"net/http"
	"net/http/httptest"

	"github.com/gin-gonic/gin"
)

// 需要登录：返回 JSON body
func requireLogin() gin.HandlerFunc {
	return func(c *gin.Context) {
		if c.GetHeader("X-Token") == "" {
			c.AbortWithStatusJSON(http.StatusUnauthorized, gin.H{
				"code":    40100,
				"message": "未登录",
			})
			return
		}
		c.Next()
	}
}

// 需要管理员：只有状态码，没有 body
func requireAdmin() gin.HandlerFunc {
	return func(c *gin.Context) {
		if c.GetHeader("X-Admin") == "" {
			c.AbortWithStatus(http.StatusForbidden)
			return
		}
		c.Next()
	}
}

func main() {
	gin.SetMode(gin.ReleaseMode)
	r := gin.New()
	r.GET("/profile", requireLogin(), func(c *gin.Context) {
		c.String(http.StatusOK, "profile")
	})
	r.GET("/admin", requireAdmin(), func(c *gin.Context) {
		c.String(http.StatusOK, "admin panel")
	})

	cases := []struct {
		path  string
		token string
	}{
		{"/profile", ""},
		{"/profile", "secret"},
		{"/admin", ""},
	}
	for _, cs := range cases {
		w := httptest.NewRecorder()
		req := httptest.NewRequest(http.MethodGet, cs.path, nil)
		if cs.token != "" {
			req.Header.Set("X-Token", cs.token)
		}
		r.ServeHTTP(w, req)
		fmt.Printf("%-9s status=%d body=%q\n", cs.path, w.Code, w.Body.String())
	}
}

package main

import (
	"bytes"
	"fmt"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"

	"github.com/gin-gonic/gin"
)

func main() {
	gin.SetMode(gin.ReleaseMode)

	// 造一个临时文件
	dir, err := os.MkdirTemp("", "gin-file")
	if err != nil {
		panic(err)
	}
	defer os.RemoveAll(dir)
	path := filepath.Join(dir, "report.txt")
	content := []byte("季度报告：营收增长 20%\n")
	if err := os.WriteFile(path, content, 0o600); err != nil {
		panic(err)
	}

	r := gin.New()
	// 下载：带 Content-Disposition，浏览器当成附件保存
	r.GET("/download", func(c *gin.Context) {
		c.FileAttachment(path, "report.txt")
	})
	// 内联：直接显示文件内容
	r.GET("/inline", func(c *gin.Context) {
		c.File(path)
	})
	// 文件流：内容来自 io.Reader，适合大文件或动态生成
	r.GET("/stream", func(c *gin.Context) {
		c.DataFromReader(http.StatusOK, int64(len(content)), "text/plain; charset=utf-8", bytes.NewReader(content), nil)
	})

	for _, p := range []string{"/download", "/inline", "/stream"} {
		w := httptest.NewRecorder()
		req := httptest.NewRequest(http.MethodGet, p, nil)
		r.ServeHTTP(w, req)
		fmt.Printf("%-9s status=%d type=%-30q disposition=%q body=%q\n",
			p, w.Code, w.Header().Get("Content-Type"), w.Header().Get("Content-Disposition"), w.Body.String())
	}
}

