import (
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"

	"github.com/gin-gonic/gin"
)

// httptest.ResponseRecorder 没有实现 http.CloseNotifier，
// 而 Gin 的 c.Stream 依赖它，所以自己包一层
type streamRecorder struct {
	*httptest.ResponseRecorder
	closed chan bool
}

func (s *streamRecorder) CloseNotify() <-chan bool {
	return s.closed
}

func main() {
	gin.SetMode(gin.ReleaseMode)
	r := gin.New()
	r.GET("/stream", func(c *gin.Context) {
		i := 0
		// step 返回 false 表示没有更多数据了，Stream 随之结束
		c.Stream(func(w io.Writer) bool {
			i++
			if _, err := fmt.Fprintf(w, "chunk-%d\n", i); err != nil {
				return false
			}
			return i < 3
		})
	})

	w := &streamRecorder{ResponseRecorder: httptest.NewRecorder(), closed: make(chan bool)}
	req := httptest.NewRequest(http.MethodGet, "/stream", nil)
	r.ServeHTTP(w, req)
	fmt.Printf("status=%d flushed=%v body=%q\n", w.Code, w.Flushed, w.Body.String())
}

package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"

	"github.com/gin-gonic/gin"
)

func main() {
	gin.SetMode(gin.ReleaseMode)
	r := gin.New()

	// 响应头要在写 body 之前设置
	r.GET("/headers", func(c *gin.Context) {
		c.Header("X-Custom", "v1")                      // c.Header 就是 Header().Set
		c.Writer.Header().Set("X-Powered-By", "gopher") // 也可以直接用标准库写法
		c.SetCookie("sid", "abc123", 3600, "/", "", false, true)
		c.JSON(http.StatusOK, gin.H{"ok": true})
	})

	// body 已经写出之后再设头：客户端收不到
	r.GET("/late", func(c *gin.Context) {
		c.String(http.StatusOK, "body first")
		c.Header("X-Late", "too late")
	})

	for _, path := range []string{"/headers", "/late"} {
		w := httptest.NewRecorder()
		req := httptest.NewRequest(http.MethodGet, path, nil)
		r.ServeHTTP(w, req)
		res := w.Result()
		fmt.Printf("%-8s custom=%q powered=%q late=%q cookie=%q\n",
			path, res.Header.Get("X-Custom"), res.Header.Get("X-Powered-By"),
			res.Header.Get("X-Late"), res.Header.Get("Set-Cookie"))
	}
}

package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"

	"github.com/gin-gonic/gin"
)

func main() {
	gin.SetMode(gin.ReleaseMode)
	r := gin.New()
	// 必须打开这个开关，NoMethod 才会生效，否则方法不对也返回 404
	r.HandleMethodNotAllowed = true

	r.NoRoute(func(c *gin.Context) {
		c.JSON(http.StatusNotFound, gin.H{"code": 40400, "message": "资源不存在"})
	})
	r.NoMethod(func(c *gin.Context) {
		c.JSON(http.StatusMethodNotAllowed, gin.H{"code": 40500, "message": "请求方法不允许"})
	})

	r.GET("/users", func(c *gin.Context) {
		c.String(http.StatusOK, "users")
	})

	cases := []struct {
		method string
		path   string
	}{
		{http.MethodGet, "/users"},
		{http.MethodGet, "/not-exist"},
		{http.MethodPost, "/users"},
	}
	for _, cs := range cases {
		w := httptest.NewRecorder()
		req := httptest.NewRequest(cs.method, cs.path, nil)
		r.ServeHTTP(w, req)
		fmt.Printf("%-6s %-11s status=%d allow=%q body=%s\n",
			cs.method, cs.path, w.Code, w.Header().Get("Allow"), w.Body.String())
	}
}
